-- Day-by-day lineups for 15 festivals in Spain/Italy/Portugal (2026).
-- Artist names only -- stage and time are null so the app's artist search works.
-- Vagos Metal Fest is deliberately not included: the database already holds an
-- equivalent lineup with cleaner artist names.

-- Date corrections confirmed by the lineup itself:
--   Guimaraes Jazz  -- programme runs 12-21 Nov, database had 5-14 Nov.
--   Time in Jazz    -- programme runs 8-16 Aug, database had 11-15 Aug.
--   AMA Music Fest  -- programme has a show on 21 Aug, database started 23 Aug.
update festival_editions e set date_from = '2026-11-12', date_to = '2026-11-21'
from festivals f where e.festival_id = f.id and f.slug = 'guimaraes-jazz' and e.year = 2026;

update festival_editions e set date_from = '2026-08-08', date_to = '2026-08-16'
from festivals f where e.festival_id = f.id and f.slug = 'time-in-jazz' and e.year = 2026;

update festival_editions e set date_from = '2026-08-21'
from festivals f where e.festival_id = f.id and f.slug = 'ama-music-festival' and e.year = 2026;

update festival_editions e set
  program = v.program,
  source = 'manual',
  updated_at = now()
from (values
